[CustomEditor(typeof(DungeonMapSettings))]
public class DungeonMapSettingsEditor:Editor {
 enum Tool { Seleccionar, Pared, Suelo, Vacío, NPC, Enemigo, Cofre, Puerta, Savepoint, Teleport, Decoración, BorrarObjeto, Interruptor }
 float cellPixels=26,gridHeight=480;bool showConfiguration=false,showProperties=true;
 Vector2Int? selectedCell;bool showZoneColors,frameSelection,frameDragging;Vector2Int frameStart;int groupZone;
 HashSet<Vector2Int> selectedCells=new HashSet<Vector2Int>(),frameBase=new HashSet<Vector2Int>();
 int decorationChoice;Tool tool;bool move;Vector2 scroll;Handle selected;string notice;
 class Handle {public UnityEngine.Object asset;public string path,label,id;public Vector2Int cell;public Color color;public bool halfDoor;public string cellField="cell";}
 DungeonMapSettings Plan {get{return (DungeonMapSettings)target;}}
 DungeonRegionSettings Regions {get{return Plan.regions!=null?Plan.regions:Plan.includeLegacyObjects?DungeonRegionSettings.Current:null;}}
 [MenuItem("Editor/Plano físico del dungeon",false,2003)]static void Open(){Selection.activeObject=DungeonMapSettings.Current;EditorGUIUtility.PingObject(Selection.activeObject);}
 List<Handle> Handles(){var list=new List<Handle>();if(Plan.entities!=null)for(int i=0;i<Plan.entities.objects.Count;i++){var e=Plan.entities.objects[i];if(e!=null)list.Add(new Handle{asset=Plan.entities,path="objects.Array.data["+i+"]",label=Label(e.kind),id=e.id,cell=e.cell,color=Tint(e.kind)});}
  if(Regions!=null)for(int i=0;i<Regions.placedEnemies.Length;i++){var e=Regions.placedEnemies[i];if(e!=null)list.Add(new Handle{asset=Regions,path="placedEnemies.Array.data["+i+"]",label="EN",id=e.id,cell=e.cell,color=Color.red});}
  var refuge=Plan.includeLegacyObjects?RefugeSettings.Current:null;if(refuge!=null){for(int i=0;i<refuge.npcs.Length;i++){var n=refuge.npcs[i];list.Add(new Handle{asset=refuge,path="npcs.Array.data["+i+"]",label="NP",id=n.id,cell=n.cell,color=Color.green});}for(int i=0;i<refuge.nodes.Length;i++){var n=refuge.nodes[i];list.Add(new Handle{asset=refuge,path="nodes.Array.data["+i+"]",label="TP",id=n.id,cell=n.cell,color=Color.magenta});}list.Add(new Handle{asset=refuge,path="",cellField="saveCell",id="refuge.save",label="SV",cell=refuge.saveCell,color=Color.cyan});list.Add(new Handle{asset=refuge,path="",cellField="exitDoorCell",id="refuge.exit",label="PU",cell=new Vector2Int(Mathf.RoundToInt(refuge.exitDoorCell.x),Mathf.FloorToInt(refuge.exitDoorCell.y)),halfDoor=true,color=Color.yellow});
   var corridor=PreservationCorridorSettings.Current;if(corridor!=null)list.Add(new Handle{asset=corridor,path="",cellField="secondDoorCell",id="corridor.door",label="PU",cell=new Vector2Int(Mathf.RoundToInt(corridor.secondDoorCell.x),Mathf.FloorToInt(corridor.secondDoorCell.y)),halfDoor=true,color=Color.yellow});}
  if(Plan.includeLegacyObjects)list.Add(new Handle{asset=Plan,path="",cellField="legacyExitDoorCell",id="legacy.exit",label="PU",cell=new Vector2Int(Mathf.RoundToInt(Plan.legacyExitDoorCell.x),Mathf.FloorToInt(Plan.legacyExitDoorCell.y)),halfDoor=true,color=Color.yellow});
  if(Plan.decorations!=null)for(int i=0;i<Plan.decorations.placements.Count;i++){var d=Plan.decorations.placements[i];if(d!=null)list.Add(new Handle{asset=Plan.decorations,path="placements.Array.data["+i+"]",label="DC",id=d.id,cell=d.cell,color=new Color(.65f,.25f,1)});}
  list.RemoveAll(h=>Plan.disabledLegacyObjects.Contains(h.id));return list;
 }
 static string Label(DungeonEntityKind kind){return kind==DungeonEntityKind.NPC?"NP":kind==DungeonEntityKind.Chest?"CF":kind==DungeonEntityKind.Door?"PU":kind==DungeonEntityKind.Savepoint?"SV":kind==DungeonEntityKind.Switch?"SW":"TP";}
 static Color Tint(DungeonEntityKind kind){return kind==DungeonEntityKind.NPC?Color.green:kind==DungeonEntityKind.Chest?new Color(1,.5f,0):kind==DungeonEntityKind.Door?Color.yellow:kind==DungeonEntityKind.Savepoint?Color.cyan:Color.magenta;}
 public override void OnInspectorGUI(){serializedObject.Update();EditorGUILayout.HelpBox("Geometría y objetos separados. Selecciona una herramienta y pulsa una casilla. Pulsa un objeto para editarlo; Mover conserva su ID. NP NPC · EN enemigo · CF cofre · PU puerta · SV savepoint · TP teleport. Los objetos antiguos se editan en su asset original.",MessageType.Info);
  showConfiguration=EditorGUILayout.Foldout(showConfiguration,"Configuración del plano",true);
  if(showConfiguration){using(new EditorGUI.DisabledScope(true))EditorGUILayout.PropertyField(serializedObject.FindProperty("mapId"));foreach(var name in new[]{"eventIds","legacyInteractions","entities","regions","decorations","includeLegacyObjects","startCell","startHeading","disabledLegacyObjects"})EditorGUILayout.PropertyField(serializedObject.FindProperty(name));EditorGUILayout.PropertyField(serializedObject.FindProperty("rows"),true);}serializedObject.ApplyModifiedProperties();
  cellPixels=EditorGUILayout.Slider("Tamaño de casillas",cellPixels,12,48);gridHeight=EditorGUILayout.Slider("Altura del área de dibujo",gridHeight,180,1100);
  if(GUILayout.Button("Ajustar cuadrícula al ancho")){cellPixels=Mathf.Clamp((EditorGUIUtility.currentViewWidth-55)/Mathf.Max(1,Plan.rows!=null&&Plan.rows.Length>0?Plan.rows[0].Length:1)-4,12,48);scroll=Vector2.zero;}
  showZoneColors=EditorGUILayout.Toggle("Colorear suelo por zona",showZoneColors);
  frameSelection=EditorGUILayout.ToggleLeft("Selección por marco — arrastra; Shift añade otro marco",frameSelection);if(frameSelection){move=false;selected=null;}
  if(!Plan.Valid){EditorGUILayout.HelpBox("Filas inválidas: solo #, . y ~ del mismo ancho.",MessageType.Error);return;}
  using(new EditorGUI.DisabledScope(EditorApplication.isPlaying)){int choice=GUILayout.SelectionGrid((int)tool,Enum.GetNames(typeof(Tool)),5);if(choice!=(int)tool){tool=(Tool)choice;move=false;}if(tool==Tool.Decoración)DecorationPalette();var handles=Handles();scroll=EditorGUILayout.BeginScrollView(scroll,GUILayout.Height(gridHeight));for(int y=Plan.rows.Length-1;y>=0;y--){EditorGUILayout.BeginHorizontal();GUILayout.Label(y.ToString(),GUILayout.Width(22));for(int x=0;x<Plan.rows[y].Length;x++){var cell=new Vector2Int(x,y);var at=handles.FindAll(h=>h.cell==cell);var previous=GUI.backgroundColor;GUI.backgroundColor=at.Count>0?at[0].color:Plan.rows[y][x]=='#'?Color.gray:Plan.rows[y][x]=='~'?new Color(.08f,.04f,.14f):new Color(.2f,.6f,.7f);var region=Regions!=null?Regions.At(cell):null;if(showZoneColors&&at.Count==0&&Plan.IsFloor(cell)&&region!=null)GUI.backgroundColor=region.editorColor;
 string text=at.Count>0?at[0].label+(at.Count>1?"+":""):Plan.rows[y][x].ToString();DrawSelectableCell(cell,new GUIContent(text,"X"+x+" / Y"+y+" — "+(region!=null?region.displayName+" ("+region.id+")":"Sin zona")),at,handles);GUI.backgroundColor=previous;}EditorGUILayout.EndHorizontal();}EditorGUILayout.EndScrollView();if(frameDragging&&Event.current.rawType==EventType.MouseUp){frameDragging=false;Repaint();}
   if(frameSelection)DrawGroupZone();else DrawCellZone();
   if(!string.IsNullOrEmpty(notice))EditorGUILayout.HelpBox(notice,MessageType.Info);if(selected!=null){selected=Handles().Find(h=>h.id==selected.id&&h.asset==selected.asset);if(selected!=null){showProperties=EditorGUILayout.Foldout(showProperties,"Propiedades del objeto seleccionado",true);if(showProperties)Properties(selected);}}
   if(GUILayout.Button("Validar y guardar mapa + objetos")){var errors=ValidatePlan();if(errors.Count>0)notice=string.Join("\n",errors.ToArray());else{AssetDatabase.SaveAssets();notice="Plano y objetos guardados.";}}
  }
 }
 void DrawSelectableCell(Vector2Int cell,GUIContent text,List<Handle> at,List<Handle> handles){
  Rect rect=GUILayoutUtility.GetRect(cellPixels,cellPixels,GUILayout.Width(cellPixels),GUILayout.Height(cellPixels));
  if(frameSelection){
   var ev=Event.current;
   if(GUI.enabled&&rect.Contains(ev.mousePosition)&&ev.button==0&&(ev.type==EventType.MouseDown||ev.type==EventType.MouseDrag)){
    if(ev.type==EventType.MouseDown){frameStart=cell;frameDragging=true;frameBase=ev.shift?new HashSet<Vector2Int>(selectedCells):new HashSet<Vector2Int>();}
    if(frameDragging){selectedCells=new HashSet<Vector2Int>(frameBase);foreach(var c in FrameCells(frameStart,cell))selectedCells.Add(c);ev.Use();Repaint();}
   }
   GUI.Box(rect,text,GUI.skin.button);
  }else if(GUI.Button(rect,text))Click(cell,at,handles);
  if(Event.current.type==EventType.Repaint&&frameSelection&&selectedCells.Contains(cell)){
   EditorGUI.DrawRect(new Rect(rect.x,rect.y,rect.width,2),Color.yellow);EditorGUI.DrawRect(new Rect(rect.x,rect.yMax-2,rect.width,2),Color.yellow);EditorGUI.DrawRect(new Rect(rect.x,rect.y,2,rect.height),Color.yellow);EditorGUI.DrawRect(new Rect(rect.xMax-2,rect.y,2,rect.height),Color.yellow);
  }
 }
 public static List<Vector2Int> FrameCells(Vector2Int a,Vector2Int b){var cells=new List<Vector2Int>();for(int y=Mathf.Min(a.y,b.y);y<=Mathf.Max(a.y,b.y);y++)for(int x=Mathf.Min(a.x,b.x);x<=Mathf.Max(a.x,b.x);x++)cells.Add(new Vector2Int(x,y));return cells;}
 public static int AssignGroupZone(DungeonMapSettings map,DungeonRegionSettings regions,IEnumerable<Vector2Int> cells,int zoneIndex){
  if(regions==null||zoneIndex<0||zoneIndex>regions.regions.Length)return 0;var destination=zoneIndex==0?null:regions.regions[zoneIndex-1];if(zoneIndex>0&&destination==null)return 0;
  var floors=new HashSet<Vector2Int>();foreach(var c in cells)if(map.IsFloor(c))floors.Add(c);if(floors.Count==0)return 0;
  Undo.RecordObject(regions,"Cambiar zona del grupo de casillas");foreach(var r in regions.regions)if(r!=null)r.cells.RemoveAll(c=>floors.Contains(c));if(destination!=null)destination.cells.AddRange(floors);EditorUtility.SetDirty(regions);return floors.Count;
 }
 void DrawGroupZone(){
  EditorGUILayout.Space();EditorGUILayout.LabelField("Grupo seleccionado: "+selectedCells.Count+" casillas",EditorStyles.boldLabel);
  if(selectedCells.Count==0){EditorGUILayout.HelpBox("Arrastra un marco sobre la cuadrícula para seleccionar. No dibuja ni coloca objetos.",MessageType.Info);return;}
  int floors=0;var zones=new HashSet<string>();foreach(var c in selectedCells)if(Plan.IsFloor(c)){floors++;var r=Regions!=null?Regions.At(c):null;zones.Add(r!=null?r.displayName+" ("+r.id+")":"Sin zona / solapada");}
  EditorGUILayout.LabelField("Suelo editable",floors+"; paredes y vacíos se conservan");EditorGUILayout.HelpBox("Zonas actuales: "+string.Join(", ",new List<string>(zones).ToArray()),MessageType.Info);
  if(Regions!=null){var names=new List<string>{"Sin zona"};foreach(var r in Regions.regions)names.Add(r!=null?r.displayName+" ("+r.id+")":"Zona inválida");groupZone=EditorGUILayout.Popup("Asignar grupo a zona",Mathf.Clamp(groupZone,0,names.Count-1),names.ToArray());using(new EditorGUI.DisabledScope(floors==0)){if(GUILayout.Button("Aplicar zona al grupo")){int count=AssignGroupZone(Plan,Regions,selectedCells,groupZone);notice=count+" casillas de suelo actualizadas. Guarda con Validar y guardar mapa + objetos.";Repaint();}}}
  if(GUILayout.Button("Limpiar selección")){selectedCells.Clear();frameDragging=false;Repaint();}
 }
 void DrawCellZone(){
  if(!selectedCell.HasValue)return;var cell=selectedCell.Value;
  EditorGUILayout.Space();EditorGUILayout.LabelField("Casilla X"+cell.x+" / Y"+cell.y,EditorStyles.boldLabel);
  if(!Plan.IsFloor(cell)){EditorGUILayout.LabelField("Terreno",Plan.rows[cell.y][cell.x]=='#'?"Pared — sin zona de suelo":"Vacío — sin zona de suelo");return;}
  if(Regions==null){EditorGUILayout.HelpBox("Asigna un asset de regiones en Configuración del plano para editar la zona.",MessageType.Info);return;}
  var names=new List<string>{"Sin zona"};int current=0,matches=0;
  for(int i=0;i<Regions.regions.Length;i++){var r=Regions.regions[i];names.Add(r!=null?r.displayName+" ("+r.id+")":"Zona inválida");if(r!=null&&r.cells.Contains(cell)){current=i+1;matches++;}}
  if(matches>1)EditorGUILayout.HelpBox("Esta casilla está en varias zonas. Elige una para corregir el solapamiento.",MessageType.Warning);
  EditorGUI.BeginChangeCheck();int next=EditorGUILayout.Popup("Zona del suelo",current,names.ToArray());
  if(EditorGUI.EndChangeCheck()){
   var destination=next==0?null:Regions.regions[next-1];if(next>0&&destination==null)return;
   Undo.RecordObject(Regions,"Cambiar zona de la casilla");
   foreach(var r in Regions.regions)if(r!=null)r.cells.RemoveAll(c=>c==cell);
   if(destination!=null)destination.cells.Add(cell);
   EditorUtility.SetDirty(Regions);notice="Zona actualizada. Usa Validar y guardar mapa + objetos para guardar.";Repaint();
  }
  var zone=Regions.At(cell);if(zone!=null)EditorGUILayout.LabelField("Apariciones",zone.CanSpawn?"Enemigos habilitados":"Sin apariciones aleatorias");
 }
 public List<string> ValidatePlan(){return DungeonMapDiagnostics.Analyze(Plan).errors;}
 public List<string> ValidateObjects(){var errors=new List<string>();if(Plan.decorations!=null)foreach(var d in Plan.decorations.placements){var error=DungeonDecorationPlanner.InvalidReason(Plan,d,Plan.decorations.Catalog!=null?Plan.decorations.Catalog.Find(d.prefabId):null);if(error!=null)errors.Add(d.id+": "+error);}if(Plan.entities!=null)errors.AddRange(Plan.entities.Validate(Plan,Regions));var start=Plan.includeLegacyObjects&&RefugeSettings.Current!=null?RefugeSettings.Current.startCell:Plan.startCell;var reachable=DungeonMapDiagnostics.Reachable(Plan,start);var ids=new HashSet<string>();foreach(var h in Handles()){if(!Plan.IsFloor(h.cell))errors.Add(h.id+": fuera del suelo");if(string.IsNullOrEmpty(h.id)||!ids.Add(h.id))errors.Add("ID de objeto vacío o duplicado: "+h.id);if(h.label=="NP"||h.label=="CF"||h.label=="PU"||h.label=="SV"||h.label=="TP"){bool accessible=h.label=="TP"&&reachable.Contains(h.cell);if(h.label!="TP")foreach(var direction in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right})if(reachable.Contains(h.cell+direction))accessible=true;if(!accessible)errors.Add(h.id+": sin acceso geométrico para interactuar");}}return errors;}
 void Click(Vector2Int cell,List<Handle> at,List<Handle> all){selectedCell=cell;if(tool==Tool.Seleccionar&&at.Count==0)selected=null;notice=null;if(move&&selected!=null&&selected.asset==Plan.decorations){var settings=Plan.decorations;var placement=settings.placements.Find(p=>p.id==selected.id);var definition=settings.Catalog.Find(placement.prefabId);var candidate=new DungeonDecorationPlacement{prefabId=placement.prefabId,cell=cell,heading=placement.heading,scale=placement.scale,localOffset=placement.localOffset};string error=DungeonDecorationPlanner.InvalidReason(Plan,candidate,definition);if(error!=null){notice=error;return;}MoveHandle(selected,cell);move=false;return;}if(move&&selected!=null){if(!Plan.IsFloor(cell)||all.Exists(h=>h.cell==cell&&h.id!=selected.id)){notice="Destino inválido u ocupado.";return;}MoveHandle(selected,cell);move=false;return;}
  if(tool==Tool.Pared||tool==Tool.Suelo||tool==Tool.Vacío){if(tool!=Tool.Suelo&&(at.Count>0||cell==Plan.startCell)){notice="Mueve o elimina los objetos antes de dibujar una pared o vacío; conserva el punto de inicio.";return;}SetTerrain(Plan,Regions,cell,tool==Tool.Pared?'#':tool==Tool.Vacío?'~':'.');return;}
  if(tool==Tool.Decoración){PlaceDecoration(cell);return;}
  if(at.Count>0){selected=at[0];if(at.Count>1){var menu=new GenericMenu();foreach(var h in at){var capture=h;menu.AddItem(new GUIContent(h.label+" "+h.id),false,()=>{selected=capture;Repaint();});}menu.ShowAsContext();}else if(tool==Tool.BorrarObjeto)Remove(selected);return;}
  if(tool==Tool.Seleccionar||tool==Tool.BorrarObjeto)return;if(!Plan.IsFloor(cell)){notice="Solo puedes colocar objetos sobre suelo.";return;}if(tool==Tool.Enemigo){if(Regions==null){notice="Asigna un asset de regiones antes de colocar enemigos.";return;}Undo.RecordObject(Regions,"Colocar enemigo");var entries=new List<PlacedEnemyDefinition>(Regions.placedEnemies);entries.Add(new PlacedEnemyDefinition{cell=cell,randomLevel=false,respawn=false});Regions.placedEnemies=entries.ToArray();EditorUtility.SetDirty(Regions);selected=Handles().Find(h=>h.id==entries[entries.Count-1].id);return;}
  if(Plan.entities==null){var data=CreateInstance<DungeonEntitySettings>();var path=AssetDatabase.GenerateUniqueAssetPath(System.IO.Path.GetDirectoryName(AssetDatabase.GetAssetPath(Plan))+"/"+Plan.name+"-Objetos.asset");AssetDatabase.CreateAsset(data,path);Undo.RecordObject(Plan,"Asignar objetos");Plan.entities=data;EditorUtility.SetDirty(Plan);Undo.RegisterCreatedObjectUndo(data,"Crear objetos del plano");}
  var kind=tool==Tool.NPC?DungeonEntityKind.NPC:tool==Tool.Cofre?DungeonEntityKind.Chest:tool==Tool.Puerta?DungeonEntityKind.Door:tool==Tool.Savepoint?DungeonEntityKind.Savepoint:tool==Tool.Interruptor?DungeonEntityKind.Switch:DungeonEntityKind.Teleport;
  Undo.RecordObject(Plan.entities,"Colocar objeto");var entity=new DungeonMapEntity{cell=cell,kind=kind,displayName=tool.ToString(),npcCatalog=RefugeSettings.Current};if(entity.npcCatalog!=null&&entity.npcCatalog.npcs.Length>0)entity.npcId=entity.npcCatalog.npcs[0].id;if(kind==DungeonEntityKind.Door)entity.heading=SuggestDoorHeading(Plan,cell);Plan.entities.objects.Add(entity);EditorUtility.SetDirty(Plan.entities);selected=Handles().Find(h=>h.id==entity.id);
 }
 public static void SetTerrain(DungeonMapSettings plan,DungeonRegionSettings regions,Vector2Int cell,char terrain){
    if(plan==null||!plan.Valid||cell.y<0||cell.y>=plan.rows.Length||cell.x<0||cell.x>=plan.rows[0].Length||(terrain!='#'&&terrain!='.'&&terrain!='~')||EditorApplication.isPlaying)return;
    Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Dibujar terreno y sincronizar zona");Undo.RecordObject(plan,"Dibujar plano");
    if(terrain!='.'&&regions!=null){Undo.RecordObject(regions,"Retirar zona del terreno");foreach(var region in regions.regions)if(region!=null)region.cells.RemoveAll(c=>c==cell);EditorUtility.SetDirty(regions);}
    var row=plan.rows[cell.y].ToCharArray();row[cell.x]=terrain;plan.rows[cell.y]=new string(row);EditorUtility.SetDirty(plan);Undo.CollapseUndoOperations(group);
   }
   public static void MoveHandleAsset(UnityEngine.Object asset,string path,string field,Vector2Int cell,bool halfDoor){var so=new SerializedObject(asset);var p=so.FindProperty(string.IsNullOrEmpty(path)?field:path+"."+field);if(p==null)return;Undo.RecordObject(asset,"Mover objeto del mapa");if(halfDoor)p.vector2Value=new Vector2(cell.x,cell.y+.5f);else p.vector2IntValue=cell;so.ApplyModifiedProperties();EditorUtility.SetDirty(asset);}
 void MoveHandle(Handle h,Vector2Int cell){MoveHandleAsset(h.asset,h.path,h.cellField,cell,h.halfDoor);h.cell=cell;SyncMimic(h);}
 void SyncMimic(Handle h){if(h.asset!=Plan.entities||Plan.entities==null||Regions==null)return;var chest=Plan.entities.objects.Find(e=>e.id==h.id);if(chest==null||string.IsNullOrEmpty(chest.mimicPlacementId))return;var placement=Array.Find(Regions.placedEnemies,e=>e.id==chest.mimicPlacementId);if(placement==null||placement.cell==chest.cell)return;Undo.RecordObject(Regions,"Mover encuentro del cofre");placement.cell=chest.cell;EditorUtility.SetDirty(Regions);}

 void Remove(Handle h){if(string.IsNullOrEmpty(h.path)){Undo.RecordObject(Plan,"Ocultar objeto heredado");Plan.disabledLegacyObjects.Add(h.id);EditorUtility.SetDirty(Plan);selected=null;return;}if(h.asset==Plan.entities&&Regions!=null){var chest=Plan.entities.objects.Find(e=>e.id==h.id);if(chest!=null&&!string.IsNullOrEmpty(chest.mimicPlacementId)){Undo.RecordObject(Regions,"Eliminar encuentro del cofre");var placements=new List<PlacedEnemyDefinition>(Regions.placedEnemies);placements.RemoveAll(e=>e.id==chest.mimicPlacementId);Regions.placedEnemies=placements.ToArray();EditorUtility.SetDirty(Regions);}}var so=new SerializedObject(h.asset);string arrayPath=h.path.Substring(0,h.path.IndexOf(".Array.data["));int index=int.Parse(h.path.Substring(h.path.LastIndexOf('[')+1).TrimEnd(']'));Undo.RecordObject(h.asset,"Eliminar objeto sin cambiar suelo");so.FindProperty(arrayPath).DeleteArrayElementAtIndex(index);so.ApplyModifiedProperties();EditorUtility.SetDirty(h.asset);selected=null;}
 void Properties(Handle h){EditorGUILayout.Space();EditorGUILayout.LabelField(h.label+" — "+h.id,EditorStyles.boldLabel);if(GUILayout.Button(move?"Pulsa la casilla destino":"Mover a otra casilla"))move=!move;if(GUILayout.Button("Eliminar objeto (conservar suelo)"))Remove(h);if(selected==null)return;var so=new SerializedObject(h.asset);so.Update();var p=string.IsNullOrEmpty(h.path)?null:so.FindProperty(h.path);if(p==null){EditorGUILayout.PropertyField(so.FindProperty(h.cellField));EditorGUILayout.ObjectField("Configuración original",h.asset,h.asset.GetType(),false);}else{
   var iterator=p.Copy();var end=iterator.GetEndProperty();bool enter=true;while(iterator.NextVisible(enter)&&!SerializedProperty.EqualContents(iterator,end)){enter=false;string n=iterator.name;if(h.asset==Plan.entities&&p.FindPropertyRelative("cityEntrance").boolValue&&Array.IndexOf(new[]{"destinationMap","destinationRegionId","destinationCell"},n)>=0)continue;if(h.asset==Plan.entities&&!EntityFieldVisible((DungeonEntityKind)p.FindPropertyRelative("kind").enumValueIndex,n,(DungeonChestKind)p.FindPropertyRelative("chestKind").enumValueIndex,(DungeonDoorKind)p.FindPropertyRelative("doorKind").enumValueIndex))continue;if(n=="heading"&&h.asset==Plan.entities&&p.FindPropertyRelative("kind").enumValueIndex==(int)DungeonEntityKind.Door)DoorHeading(iterator,h.cell);else if(n=="prefabId")DecorationDropdown(iterator,h.asset as DungeonDecorationSettings);else if(n=="speciesId")EnemyDropdown(iterator);else if(n=="npcId")NpcDropdown(iterator,p.FindPropertyRelative("npcCatalog"));else if(n=="contentId"||n=="requiredKeyId")ItemDropdown(iterator);else if(n=="mimicPlacementId"||n=="guardPlacementId")PlacementDropdown(iterator);else if(n=="destinationRegionId")RegionDropdown(iterator);else if(n=="revealedRegionIds")TeleportRegionSelection.Draw(iterator,Regions);else if(n=="destinations")Destinations(iterator,h.id);else EditorGUILayout.PropertyField(iterator,true);}
  }if(so.ApplyModifiedProperties()){EditorUtility.SetDirty(h.asset);SyncMimic(h);}
  if(h.asset==Plan.entities){var index=Plan.entities.objects.FindIndex(e=>e.id==h.id);if(index>=0&&Plan.entities.objects[index].kind==DungeonEntityKind.Chest&&Plan.entities.objects[index].chestKind==DungeonChestKind.Mimic&&GUILayout.Button("Crear encuentro Mimic asociado"))CreateMimic(Plan.entities.objects[index]);}
 }
 void DecorationPalette(){var catalog=Plan.decorations!=null?Plan.decorations.Catalog:DungeonDecorationCatalog.Current;if(catalog==null){EditorGUILayout.HelpBox("Crea el catálogo de decoración primero.",MessageType.Warning);return;}var names=new List<string>();foreach(var d in catalog.entries)names.Add(d.displayName+" / "+d.mount);decorationChoice=EditorGUILayout.Popup("Decoración a colocar",Mathf.Clamp(decorationChoice,0,names.Count-1),names.ToArray());var prefab=catalog.entries[decorationChoice].prefab;var preview=AssetPreview.GetAssetPreview(prefab);if(preview!=null)GUILayout.Label(preview,GUILayout.Width(100),GUILayout.Height(80));if(Plan.decorations!=null&&GUILayout.Button("Abrir densidad y decoración automática")){Selection.activeObject=Plan.decorations;EditorGUIUtility.PingObject(Plan.decorations);}}
 void PlaceDecoration(Vector2Int cell){var catalog=Plan.decorations!=null?Plan.decorations.Catalog:DungeonDecorationCatalog.Current;if(catalog==null||catalog.entries.Length==0)return;var def=catalog.entries[Mathf.Clamp(decorationChoice,0,catalog.entries.Length-1)];int heading=0;if(def.mount==DecorationMount.Wall||def.mount==DecorationMount.Room){heading=DungeonDecorationPlanner.WallHeading(Plan,cell);if(heading<0){notice="Escoge una casilla junto a pared.";return;}}if(def.mount==DecorationMount.Door){var door=Plan.entities!=null?Plan.entities.objects.Find(e=>e.kind==DungeonEntityKind.Door&&e.cell==cell):null;if(door==null){notice="Escoge una puerta del mapa.";return;}heading=door.heading;}var placement=new DungeonDecorationPlacement{prefabId=def.id,cell=cell,heading=heading};string error=DungeonDecorationPlanner.InvalidReason(Plan,placement,def);if(error!=null){notice=error;return;}
  if(Plan.decorations==null){var data=CreateInstance<DungeonDecorationSettings>();data.catalog=catalog;data.regions=Regions;string path=AssetDatabase.GenerateUniqueAssetPath(System.IO.Path.GetDirectoryName(AssetDatabase.GetAssetPath(Plan))+"/"+Plan.name+"-Decoración.asset");AssetDatabase.CreateAsset(data,path);Undo.RecordObject(Plan,"Asignar decoración");Plan.decorations=data;EditorUtility.SetDirty(Plan);Undo.RegisterCreatedObjectUndo(data,"Crear decoración del mapa");}var same=Plan.decorations.placements.Find(p=>p.cell==cell&&Plan.decorations.Catalog.Find(p.prefabId)!=null&&Plan.decorations.Catalog.Find(p.prefabId).mount==def.mount&&(def.mount!=DecorationMount.Wall||p.heading==heading));if(same!=null){selected=Handles().Find(h=>h.id==same.id);notice="Decoración existente seleccionada; puedes editarla o moverla.";return;}Undo.RecordObject(Plan.decorations,"Colocar decoración");Plan.decorations.placements.Add(placement);EditorUtility.SetDirty(Plan.decorations);selected=Handles().Find(h=>h.id==placement.id);notice="Decoración colocada sin cambiar suelo ni entidades.";
 }
 static void DecorationDropdown(SerializedProperty p,DungeonDecorationSettings settings){var catalog=settings!=null?settings.Catalog:DungeonDecorationCatalog.Current;if(catalog==null)return;var names=new List<string>{"Seleccionar"};var ids=new List<string>{""};foreach(var d in catalog.entries){names.Add(d.displayName+" / "+d.mount);ids.Add(d.id);}EditorGUI.BeginChangeCheck();int next=EditorGUILayout.Popup("Decoración",Mathf.Max(0,ids.IndexOf(p.stringValue)),names.ToArray());if(EditorGUI.EndChangeCheck())p.stringValue=ids[next];}
 void DoorHeading(SerializedProperty p,Vector2Int cell){
  p.intValue=EditorGUILayout.Popup("Orientación de la puerta",Mathf.Clamp(p.intValue,0,3),new[]{"Norte — borde superior","Este — borde derecho","Sur — borde inferior","Oeste — borde izquierdo"});
  if(GUILayout.Button("Detectar orientación del pasillo"))p.intValue=SuggestDoorHeading(Plan,cell,p.intValue);
  EditorGUILayout.HelpBox("La puerta se coloca en el borde indicado de la casilla. Norte/Sur cruzan un paso vertical; Este/Oeste cruzan un paso horizontal. En habitaciones abiertas elige el borde manualmente.",MessageType.Info);
 }
 public static int SuggestDoorHeading(DungeonMapSettings plan,Vector2Int cell,int fallback=0){
  var dirs=new[]{Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};int best=fallback,score=0;
  for(int i=0;i<4;i++){var d=dirs[i];var next=cell+d;if(!plan.IsFloor(cell)||!plan.IsFloor(next))continue;var side=new Vector2Int(-d.y,d.x);int value=0;foreach(var c in new[]{cell+side,cell-side,next+side,next-side})if(!plan.IsFloor(c))value++;if(value>score){score=value;best=i;}}
  return best;
 }
 public static bool EntityFieldVisible(DungeonEntityKind kind,string name,DungeonChestKind chest=DungeonChestKind.Normal,DungeonDoorKind door=DungeonDoorKind.Normal){
  if(Array.IndexOf(new[]{"id","displayName","kind","cell","heading","interaction"},name)>=0)return true;
  switch(kind){
   case DungeonEntityKind.Switch:return name=="switchInitiallyActive";
   case DungeonEntityKind.NPC:return name=="npcCatalog"||name=="npcId"||name=="dialogue";
   case DungeonEntityKind.Chest:return name=="chestKind"||name=="guardPlacementId"||(chest==DungeonChestKind.Mimic?name=="mimicPlacementId":name=="contentId"||name=="quantity");
   case DungeonEntityKind.Door:return name=="cityEntrance"||name=="doorKind"||name=="doorSettings"||name=="doorInitiallyOpen"||(door==DungeonDoorKind.Locked&&name=="requiredKeyId")||(door==DungeonDoorKind.Transition&&(name=="destinationRegionId"||name=="destinationMap"||name=="destinationCell"));
   case DungeonEntityKind.Savepoint:return name=="heal"||name=="save";
   case DungeonEntityKind.Teleport:return name=="initiallyActive"||name=="requiresActivation"||name=="destinations"||name=="revealedRegionIds";
  }return false;
 }
